import math
import unittest
from fractions import Fraction
from solution import compute_covered_area


class ComputeCoveredAreaTests(unittest.TestCase):
    def test_normal_values_and_float_result(self):
        result = compute_covered_area(10, 4, 0.25)
        self.assertEqual(result, 10.0)
        self.assertIs(type(result), float)

    def test_integer_and_fraction_inputs(self):
        result = compute_covered_area(3, Fraction(5, 2), Fraction(1, 2))
        self.assertEqual(result, 3.75)
        self.assertIs(type(result), float)

    def test_coverage_boundaries(self):
        self.assertEqual(compute_covered_area(2, 5, 0), 0.0)
        self.assertEqual(compute_covered_area(2, 5, 1), 10.0)

    def test_rejects_boolean_and_non_real_types(self):
        cases = [
            (True, 2, 0.5),
            (2, False, 0.5),
            (2, 3, True),
            ("2", 3, 0.5),
            (2, complex(3, 0), 0.5),
            (2, 3, None),
        ]
        for args in cases:
            with self.subTest(args=args):
                with self.assertRaises(TypeError):
                    compute_covered_area(*args)

    def test_rejects_non_finite_values(self):
        for value in (math.inf, -math.inf, math.nan):
            for position in range(3):
                args = [2.0, 3.0, 0.5]
                args[position] = value
                with self.subTest(value=value, position=position):
                    with self.assertRaises(ValueError):
                        compute_covered_area(*args)

    def test_rejects_nonpositive_dimensions(self):
        for args in ((0, 2, 0.5), (-1, 2, 0.5), (2, 0, 0.5), (2, -1, 0.5)):
            with self.subTest(args=args):
                with self.assertRaises(ValueError):
                    compute_covered_area(*args)

    def test_rejects_coverage_outside_closed_interval(self):
        for coverage in (-0.0001, 1.0001, -1, 2):
            with self.subTest(coverage=coverage):
                with self.assertRaises(ValueError):
                    compute_covered_area(2, 3, coverage)


if __name__ == "__main__":
    unittest.main()

